;; Code generated by `go tool whim skel -clj` from a C translation unit; DO NOT EDIT.
;; 1699 of 1707 functions written (1624 structured, 74 state machines), 8 the runtime's; the rest are stubs that throw, with the reason.

(ns whim.editor
  (:require [whim.cljhost])
  (:import [whim.rt BytePtr ShortPtr IntPtr LongPtr BoolPtr Ptr Rt Ga Struct]))

(set! *warn-on-reflection* true)
(set! *unchecked-math* :warn-on-boxed)

;; C's conversion of a long to each integer type narrower than 64 bits.
(defmacro ^:private i8 [x] `(long (unchecked-byte ~x)))
(defmacro ^:private u8 [x] `(bit-and ~x 0xff))
(defmacro ^:private i16 [x] `(long (unchecked-short ~x)))
(defmacro ^:private u16 [x] `(bit-and ~x 0xffff))
(defmacro ^:private i32 [x] `(long (unchecked-int ~x)))
(defmacro ^:private u32 [x] `(bit-and ~x 0xffffffff))

(declare
  ask-yesno change-indent char-avail char2cells cmp-keyvalue-value-n curs-columns do-more-prompt do-outofmem-msg
