          false)
    -2
      (do (g! ed vim-handle-signal-blocked false)
          (if (== (g ed vim-handle-signal-got-signal) 0)
            false
            (do (whim.cljhost/host-raise ed (g ed vim-handle-signal-got-signal))
                (g! ed vim-handle-signal-got-signal 0)
                false)))
    (if (g ed vim-handle-signal-blocked)
      (do (g! ed vim-handle-signal-got-signal sig)
          (g! ed got-int (e TRUE))
          false)
      true)))

