  (aset ^ints (.-wo-ve-flags to) 0 (unchecked-int (bit-and (aget ^ints (.-wo-ve-flags from) 0) 0xffffffff)))
  (aset ^ints (.-wo-wrap to) 0 (unchecked-int (long (aget ^ints (.-wo-wrap from) 0))))
