;; C: buflist_setfpos
(defn buflist-setfpos [^Editor ed ^S_file_buffer buf ^S_window_S win lnum col copy-options]
  (let [lnum (long lnum)
        col (long col)
        ^longs tl__ (long-array 1)
        ^objects to__ (object-array 1)
        ^S_wininfo_S wip (.b-wininfo buf)
        l__1 (loop [^S_wininfo_S wip wip]
               (if (some? wip)
                 (if (identical? (.wi-win wip) win)
                   (do (aset to__ 0 wip)
                       0)
                   (let [^S_wininfo_S wip (.wi-next wip)]
                     (recur wip)))
                 (do (aset to__ 0 wip)
                     0)))
        ^S_wininfo_S wip (aget to__ 0)
        j__2 (if (nil? wip)
               (let [^S_wininfo_S wip (new-S_wininfo_S)]
                 (.set-wi-win wip win)
                 (if (== lnum 0)
                   (let [lnum 1]
                     (aset tl__ 0 lnum)
                     (aset to__ 0 wip)
                     0)
                   (do (aset tl__ 0 lnum)
                       (aset to__ 0 wip)
                       0)))
               (do (if (nil? (.wi-prev wip))
                     (.set-b-wininfo buf (.wi-next wip))
                     (.set-wi-next ^S_wininfo_S (.wi-prev wip) (.wi-next wip)))
                   (when-not (nil? (.wi-next wip))
                     (.set-wi-prev ^S_wininfo_S (.wi-next wip) (.wi-prev wip)))
                   (if (and copy-options (.wi-optset wip))
                     (do (clear-winopt ed (.-wi-opt wip))
                         (aset tl__ 0 lnum)
                         (aset to__ 0 wip)
                         0)
                     (do (aset tl__ 0 lnum)
                         (aset to__ 0 wip)
                         0))))
        lnum (aget tl__ 0)
        ^S_wininfo_S wip (aget to__ 0)]
    (when-not (== lnum 0)
      (.set-lnum ^T_pos_T (.-wi-fpos wip) lnum)
      (.set-col ^T_pos_T (.-wi-fpos wip) col))
    (when (and copy-options (some? win))
      (copy-winopt ed (.-w-onebuf-opt win) (.-wi-opt wip))
      (.set-wi-optset wip (boolean true)))
    (.set-wi-next wip (.b-wininfo buf))
    (.set-b-wininfo buf wip)
    (.set-wi-prev wip nil)
    (when-not (nil? (.wi-next wip))
      (.set-wi-prev ^S_wininfo_S (.wi-next wip) wip)
      nil)))

