        flags (long flags)]
    (if (> lnum (.ml-line-count ^S_memline (.-b-ml buf)))
      false
      (if (== (.ml-line-lnum ^S_memline (.-b-ml buf)) 0)
        (ml-append-int ed buf lnum line len flags)
        (do (ml-flush-line ed buf)
            (ml-append-int ed buf lnum line len flags))))))

;; C: ml_append_flags
