  (let [lnum (long lnum)
        len (long len)
        flags (long flags)]
    (if (and (nil? (.ml-root ^S_memline (.-b-ml (g ed curbuf)))) (not (open-buffer ed)))
      false
      (ml-append-flush ed (g ed curbuf) lnum line len flags))))

;; C: ml_append
(defn ml-append [^Editor ed ^long lnum ^BytePtr line ^long len]
  (ml-append-flags ed lnum line len 0))

;; C: one_adjust
(defn one-adjust [^Editor ed lnum line1 line2 amount amount-after]
  (let [lnum (long lnum)
        line1 (long line1)
        line2 (long line2)
        amount (long amount)
        amount-after (long amount-after)]
    (if (and (>= lnum line1) (<= lnum line2))
      (if (== amount (e LONG_MAX))
        0
        (+ lnum amount))
      (if (and (not (zero? amount-after)) (> lnum line2))
        (+ lnum amount-after)
        lnum))))

