;; C: replace_join
(defn replace-join [^Editor ed ^long off]
  (let [^longs tl__ (long-array 1)
        ^objects to__ (object-array 1)
        i (i32 (g ed replace-stack-nr))]
    (loop [off off
           i i]
      (let [i (i32 (dec i))]
        (when (>= i 0)
          (let [t1 (== (bit-and (.at (g ed replace-stack) i) 0xff) (e NUL))
                j__1 (if t1
                       (let [t2 off
                             off (i32 (dec off))
                             t1 (<= t2 0)]
                         (aset tl__ 0 off)
                         (aset to__ 0 (Boolean/valueOf (boolean t1)))
                         0)
                       (do (aset tl__ 0 off)
                           (aset to__ 0 (Boolean/valueOf (boolean t1)))
                           0))
                off (aget tl__ 0)
                t1 (boolean (aget to__ 0))]
            (if t1
              (do (g! ed replace-stack-nr (dec (g ed replace-stack-nr)))
                  (Rt/memmove (.add (g ed replace-stack) i) (.add (.add (g ed replace-stack) i) 1) (- (g ed replace-stack-nr) i))
                  nil)
              (recur off i))))))))

;; C: truncate_spaces
(defn truncate-spaces [^Editor ed ^BytePtr line ^long len]
  (let [i (i32 (- (i32 len) 1))]
    (loop [i i]
      (if (and (>= i 0) (or (== (bit-and (.at line i) 0xff) 32) (== (bit-and (.at line i) 0xff) 9)))
        (do (when-not (zero? (bit-and (g ed State) (e REPLACE_FLAG)))
              (replace-join ed 0))
            (let [i (i32 (dec i))]
              (recur i)))
        (do (.set line (i32 (+ i 1)) (unchecked-byte (e NUL)))
            nil)))))

;; C: changed_lines_buf
(defn changed-lines-buf [^Editor ed ^S_file_buffer buf lnum lnume xtra]
  (let [lnum (long lnum)
        lnume (long lnume)
        xtra (long xtra)]
    (if (.b-mod-set buf)
      (do (when (< lnum (.b-mod-top buf))
            (.set-b-mod-top buf lnum))
          (when (< lnum (.b-mod-bot buf))
            (.set-b-mod-bot buf (+ (.b-mod-bot buf) xtra))
            (when (< (.b-mod-bot buf) lnum)
              (.set-b-mod-bot buf lnum)))
          (when (> (+ lnume xtra) (.b-mod-bot buf))
            (.set-b-mod-bot buf (+ lnume xtra)))
          (.set-b-mod-xlines buf (+ (.b-mod-xlines buf) xtra))
          nil)
      (do (.set-b-mod-set buf (boolean true))
          (.set-b-mod-top buf lnum)
          (.set-b-mod-bot buf (+ lnume xtra))
          (.set-b-mod-xlines buf xtra)
          nil))))

;; C: changed_lines
(defn changed-lines [^Editor ed lnum col lnume xtra]
  (let [lnum (long lnum)
        col (long col)
        lnume (long lnume)
        xtra (long xtra)]
    (changed-lines-buf ed (g ed curbuf) lnum lnume xtra)
    (changed-common ed lnum col lnume xtra)
    nil))

;; C: mark_col_adjust
(defn mark-col-adjust [^Editor ed lnum mincol lnum-amount col-amount spaces-removed]
  (let [lnum (long lnum)
        mincol (long mincol)
        lnum-amount (long lnum-amount)
        col-amount (long col-amount)
        spaces-removed (long spaces-removed)
        fnum (.b-fnum (g ed curbuf))]
    (when-not (or (and (== col-amount 0) (== lnum-amount 0)) (not (zero? (bit-and (.cmod-flags (g ed cmdmod)) (e CMOD_LOCKMARKS)))))
      (let [i 0]
        (loop [i i]
          (if (< i 26)
            (let [^T_pos_T posp (Ptr/ref (Ptr. ^objects (.-b-namedm (g ed curbuf)) i))]
              (when (and (== (.lnum posp) lnum) (>= (.col posp) mincol))
                (.set-lnum posp (+ (.lnum posp) lnum-amount))
                (if (and (< col-amount 0) (<= (.col posp) (i32 (- col-amount))))
                  (.set-col posp 0)
                  (if (< (.col posp) spaces-removed)
                    (.set-col posp (i32 (+ col-amount spaces-removed)))
                    (.set-col posp (i32 (+ (.col posp) col-amount))))))
              (let [i (i32 (inc i))]
                (recur i)))
            (let [^T_pos_T posp (.-b-last-insert (g ed curbuf))]
              (when (and (== (.lnum posp) lnum) (>= (.col posp) mincol))
                (.set-lnum posp (+ (.lnum posp) lnum-amount))
                (if (and (< col-amount 0) (<= (.col posp) (i32 (- col-amount))))
                  (.set-col posp 0)
                  (if (< (.col posp) spaces-removed)
                    (.set-col posp (i32 (+ col-amount spaces-removed)))
                    (.set-col posp (i32 (+ (.col posp) col-amount))))))
              (let [^T_pos_T posp (.-b-last-change (g ed curbuf))]
                (when (and (== (.lnum posp) lnum) (>= (.col posp) mincol))
                  (.set-lnum posp (+ (.lnum posp) lnum-amount))
                  (if (and (< col-amount 0) (<= (.col posp) (i32 (- col-amount))))
                    (.set-col posp 0)
                    (if (< (.col posp) spaces-removed)
                      (.set-col posp (i32 (+ col-amount spaces-removed)))
                      (.set-col posp (i32 (+ (.col posp) col-amount))))))
                (let [i 0]
