        (do (whim.cljhost/host-message ed (BytePtr/lit "\015\n") -1 (e TRUE))
            nil)
        (do (whim.cljhost/host-message ed (BytePtr/lit "\n") -1 (e FALSE))
            nil))
      (do (out-char ed 10)
          nil))
    (do (restore-cterm-colors ed)
