(defn vim-regsub-multi [^Editor ed ^T_regmmatch_T rmp lnum ^BytePtr source ^BytePtr dest destlen flags]
  (let [lnum (long lnum)
        destlen (long destlen)
        flags (long flags)
        ^T_regexec_T rex-save (new-T_regexec_T)
        rex-in-use-save (g ed rex-in-use)]
    (when-not (zero? (g ed rex-in-use))
      (.set rex-save (g ed rex)))
    (g! ed rex-in-use (e TRUE))
    (.set-reg-match (g ed rex) nil)
    (.set-reg-mmatch (g ed rex) rmp)
    (.set-reg-buf (g ed rex) (g ed curbuf))
    (.set-reg-firstlnum (g ed rex) lnum)
    (.set-reg-maxline (g ed rex) (- (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) lnum))
    (.set-reg-line-lbr (g ed rex) (boolean false))
    (let [result (long (vim-regsub-both ed source dest destlen flags))]
      (g! ed rex-in-use rex-in-use-save)
      (if (zero? (g ed rex-in-use))
        result
        (do (.set (g ed rex) rex-save)
            result)))))

