(defn getcmdline ^BytePtr [^Editor ed firstc count_ indent do-concat]
  (let [firstc (long firstc)
        count_ (long count_)
        indent (long indent)
        do-concat (long do-concat)]
    (getcmdline-int ed firstc count_ indent true)))

(defn getexline ^BytePtr [^Editor ed ^long c ^long indent ^long options]
  (if (and (not (zero? (g ed exec-from-reg))) (== (long (vpeekc ed)) 58))
    (do (vgetc ed)
        (getcmdline ed c 1 indent options))
    (getcmdline ed c 1 indent options)))

;; C: ex_at
(defn ex-at [^Editor ed ^S_exarg eap]
  (let [prev-len (.tb-len (g ed typebuf))
        _ (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) (.line2 eap))
        _ (check-cursor-col ed)
        c (bit-and (.get ^BytePtr (aget ^objects (.-arg eap) 0)) 0xff)
        c (if (or (== c (e NUL)) (and (== c 42) (== (bit-and (.get ^BytePtr (aget ^objects (.-cmd eap) 0)) 0xff) 42)))
            64
            c)]
    (if (do-execreg ed c true (some? (vim-strchr ed (aget (g ed p-cpo) 0) (e CPO_EXECBUF))) true)
      (let [save-efr (g ed exec-from-reg)]
        (g! ed exec-from-reg (e TRUE))
        (loop []
          (if (or (not (stuff-empty? ed)) (> (.tb-len (g ed typebuf)) prev-len))
            (do (do-cmdline ed nil getexline 67)
                (recur))
            (do (g! ed exec-from-reg save-efr)
                nil))))
      (do (beep-flush ed)
          nil))))

