        ^T_visualinfo_T visualinfo (new-T_visualinfo_T)]
    (loop [st 0
           undo undo
           ^Ptr newarray nil
           oldsize 0
           newsize 0
           top 0
           bot 0
           lnum 0
           newlnum 0
           i 0
           ^S_u_entry uep nil
           ^S_u_entry newlist nil
           old-flags 0
           new-flags 0
           empty-buffer false
           ^S_u_header curhead nil]
      (case st
        0
          (let [^Ptr newarray nil
                newlnum (e LONG_MAX)
                _ (.set new-curpos (.-w-cursor (g ed curwin)))
                ^S_u_entry newlist nil
                ^S_u_header curhead (.b-u-curhead (g ed curbuf))
                _ (block-autocmds ed)
                old-flags (.uh-flags curhead)
                new-flags (i32 (+ (if (zero? (long (aget ^ints (.-b-changed (g ed curbuf)) 0))) 0 (e UH_CHANGED)) (if (zero? (bit-and (.ml-flags ^S_memline (.-b-ml (g ed curbuf))) (e ML_EMPTY))) 0 (e UH_EMPTYBUF))))
