                _ (.set visualinfo (.-b-visual (g ed curbuf)))
                _ (.set-lnum ^T_pos_T (.-b-op-start (g ed curbuf)) (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))))
                _ (.set-col ^T_pos_T (.-b-op-start (g ed curbuf)) 0)
                _ (.set-lnum ^T_pos_T (.-b-op-end (g ed curbuf)) 0)
