            (recur 1 undo newarray oldsize newsize top bot lnum newlnum i uep newlist old-flags new-flags empty-buffer curhead))
        1
          (if (some? uep)
            (let [top (.ue-top uep)
                  bot (.ue-bot uep)
                  bot (if (== bot 0)
                        (+ (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) 1)
                        bot)]
              (if (or (> top (.ml-line-count ^S_memline (.-b-ml (g ed curbuf)))) (>= top bot) (> bot (+ (.ml-line-count ^S_memline (.-b-ml (g ed curbuf))) 1)))
