                      newsize (.ue-size uep)
                      lnum (.lnum ^T_pos_T (.-uh-cursor curhead))]
                  (if (and (>= lnum top) (<= lnum (+ top newsize 1)))
                    (do (.set new-curpos (.-uh-cursor curhead))
                        (let [newlnum -1]
                          (recur 5 undo newarray oldsize newsize top bot lnum newlnum i uep newlist old-flags new-flags empty-buffer curhead)))
