                                                (do (.set-col pos (i32 (+ (.col pos) (.col ^T_pos_T (.-start oap)))))
                                                    (i32 (- length (.col ^T_pos_T (.-start oap)))))
                                                length)]
                                   (if (== (.lnum pos) (.lnum ^T_pos_T (.-end oap)))
                                     (let [length (long (ml-get-len ed (.lnum ^T_pos_T (.-end oap))))]
                                       (when (>= (.col ^T_pos_T (.-end oap)) length)
                                         (.set-col ^T_pos_T (.-end oap) (i32 (- length 1))))
                                       (i32 (+ (i32 (- (.col ^T_pos_T (.-end oap)) (.col pos))) 1)))
                                     length))))
