            (do (when-not (zero? change-cnt)
                  (changed-lines ed (.lnum ^T_pos_T (.-start oap)) 0 (+ (.lnum ^T_pos_T (.-end oap)) 1) 0))
                (when (and (zero? change-cnt) (not (zero? (.is-VIsual oap))))
