        ^BytePtr t1 p
        ^BytePtr p (.add p 1)
        modec (bit-and (.get t1) 0xff)]
    (if (== modec 105)
      (let [mode (e MODE_INSERT)]
        (.put cmdp p)
        mode)
      (if (== modec 99)
        (let [mode (e MODE_CMDLINE)]
          (.put cmdp p)
          mode)
        (if (and (== modec 110) (not (== (bit-and (.get p) 0xff) 111)))
          (let [mode (e MODE_NORMAL)]
            (.put cmdp p)
            mode)
          (if (== modec 118)
            (let [mode 66]
              (.put cmdp p)
              mode)
            (if (== modec 120)
              (let [mode (e MODE_VISUAL)]
                (.put cmdp p)
                mode)
              (if (== modec 115)
                (let [mode (e MODE_SELECT)]
                  (.put cmdp p)
                  mode)
                (if (== modec 111)
