;; C: match_keyprotocol
(defn match-keyprotocol ^long [^Editor ed ^BytePtr term]
  (let [^objects p (object-array 1)
        ^T_regmatch_T regmatch (new-T_regmatch_T)
        ^longs tl__ (long-array 2)
        len (i32 (+ (i32 (long (musl-strlen ed (aget (g ed p-kpc) 0)))) 1))
        ^BytePtr buf (BytePtr/alloc len)
        ret (e KEYPROTOCOL_FAIL)]
    (aset p 0 (aget (g ed p-kpc) 0))
    (loop []
      (if (== (bit-and (.get ^BytePtr (aget p 0)) 0xff) (e NUL))
        (e KEYPROTOCOL_NONE)
        (do (copy-option-part ed (Ptr. p 0) buf len (BytePtr/lit ","))
            (let [^BytePtr colon (vim-strchr ed buf 58)]
              (if (or (nil? colon) (BytePtr/eq colon buf) (== (bit-and (.at colon 1) 0xff) (e NUL)))
                ret
                (do (.put colon (unchecked-byte (e NUL)))
                    (let [j__1 (if (== (long (musl-strcmp ed (.add colon 1) (BytePtr/lit "none"))) 0)
                                 (let [prot (e KEYPROTOCOL_NONE)]
                                   (aset tl__ 0 prot)
                                   0)
                                 (if (== (long (musl-strcmp ed (.add colon 1) (BytePtr/lit "mok2"))) 0)
                                   (let [prot (e KEYPROTOCOL_MOK2)]
                                     (aset tl__ 0 prot)
                                     0)
                                   (if (== (long (musl-strcmp ed (.add colon 1) (BytePtr/lit "kitty"))) 0)
                                     (let [prot (e KEYPROTOCOL_KITTY)]
                                       (aset tl__ 0 prot)
                                       0)
                                     1)))]
                      (case (long j__1)
                        0
                          (let [prot (aget tl__ 0)]
                            (.zero regmatch)
                            (.set-rm-ic regmatch (boolean true))
                            (.set-regprog regmatch (vim-regcomp ed buf (e RE_MAGIC)))
                            (if (nil? (.regprog regmatch))
                              ret
                              (let [match (and (some? term) (vim-regexec ed regmatch term 0))]
                                (vim-regfree ed (.regprog regmatch))
                                (if match
                                  prot
                                  (recur)))))
                        1
                          ret))))))))))

;; C: apply_builtin_tcap
(defn apply-builtin-tcap [^Editor ed ^BytePtr term ^Ptr entries overwrite]
  (let [^bytes name_ (byte-array 2)]
    (loop [st 0
           ^BytePtr term term
           ^Ptr entries entries
           overwrite overwrite
           term-8bit false
           ^Ptr p nil
           ^BytePtr s nil
           ^BytePtr t nil]
      (case st
        0
          (let [term-8bit (term-is-8bit? ed term)
                ^Ptr p entries]
            (recur 1 term entries overwrite term-8bit p s t))
        1
          (when (and (not (== (.bt-entry ^T_tcap_entry_T (.get p)) 0)) (not (== (.bt-entry ^T_tcap_entry_T (.get p)) (e BT_EXTRA_KEYS))))
            (if (>= (.bt-entry ^T_tcap_entry_T (.get p)) 0)
              (if (or (nil? (aget (g ed term-strings) (.bt-entry ^T_tcap_entry_T (.get p)))) (BytePtr/eq ^BytePtr (aget (g ed term-strings) (.bt-entry ^T_tcap_entry_T (.get p))) (g ed empty-option)) overwrite)
                (if (and term-8bit (not (== (long (term-7to8bit ed (.bt-string ^T_tcap_entry_T (.get p)))) 0)))
                  (let [^BytePtr s (vim-strsave ed (.bt-string ^T_tcap_entry_T (.get p)))
                        ^BytePtr t s]
                    (recur 2 term entries overwrite term-8bit p s t))
                  (do (aset (g ed term-strings) (.bt-entry ^T_tcap_entry_T (.get p)) (.bt-string ^T_tcap_entry_T (.get p)))
                      (recur 3 term entries overwrite term-8bit p s t)))
                (recur 3 term entries overwrite term-8bit p s t))
              (do (aset name_ 0 (unchecked-byte (bit-and (i32 (- (.bt-entry ^T_tcap_entry_T (.get p)))) 255)))
                  (aset name_ 1 (unchecked-byte (bit-and (bit-shift-right (u32 (- (.bt-entry ^T_tcap_entry_T (.get p)))) 8) 255)))
                  (if (or (nil? (find-termcode ed (BytePtr. name_ 0))) overwrite)
                    (do (add-termcode ed (BytePtr. name_ 0) (.bt-string ^T_tcap_entry_T (.get p)) (if term-8bit 1 0))
                        (recur 3 term entries overwrite term-8bit p s t))
                    (recur 3 term entries overwrite term-8bit p s t)))))
        2
          (if (zero? (bit-and (.get t) 0xff))
            (do (aset (g ed term-strings) (.bt-entry ^T_tcap_entry_T (.get p)) s)
                (set-term-option-alloced ed (Ptr. (g ed term-strings) (.bt-entry ^T_tcap_entry_T (.get p))))
                (recur 3 term entries overwrite term-8bit p s t))
            (do (when-not (zero? (long (term-7to8bit ed t)))
                  (.put t (unchecked-byte (long (term-7to8bit ed t))))
                  (Rt/memmove (.add t 1) (.add t 2) (+ (long (musl-strlen ed (.add t 2))) 1)))
                (let [^BytePtr t (.add t 1)]
                  (recur 2 term entries overwrite term-8bit p s t))))
        3
          (let [^Ptr p (.add p 1)]
            (recur 1 term entries overwrite term-8bit p s t))))))

;; C: accept_modifiers_for_function_keys
(defn accept-modifiers-for-function-keys [^Editor ed]
  (let [^T_regmatch_T regmatch (new-T_regmatch_T)]
    (.zero regmatch)
    (.set-rm-ic regmatch (boolean true))
    (.set-regprog regmatch (vim-regcomp ed (BytePtr/lit "^\033[\\d\\+\\~$") (e RE_MAGIC)))
    (let [i 0]
      (loop [i i]
        (if (< i (g ed tc-len))
          (when-not (nil? (.regprog regmatch))
            (when-not (and (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 0) 0xff) 80) (or (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 1) 0xff) 83) (== (bit-and (aget ^bytes (.-name_ ^S_termcode (.at (g ed termcodes) i)) 1) 0xff) 69)))
              (let [^BytePtr s (.code ^S_termcode (.at (g ed termcodes) i))]
                (when (and (some? s) (vim-regexec ed regmatch s 0))
                  (let [len (long (musl-strlen ed s))
                        ^BytePtr ns_ (BytePtr/alloc (+ len 3))]
                    (Rt/memmove ns_ s (- len 1))
                    (Rt/memmove (.add (.add ns_ len) (- 1)) (BytePtr/lit ";*~") 4)
                    (.set-code ^S_termcode (.at (g ed termcodes) i) ns_)
                    (.set-len ^S_termcode (.at (g ed termcodes) i) (i32 (+ (.len ^S_termcode (.at (g ed termcodes) i)) 2)))
                    (adjust-modlen ed i)))))
            (let [i (i32 (inc i))]
              (recur i)))
          (do (vim-regfree ed (.regprog regmatch))
              nil))))))

;; C: apply_keyprotocol
(defn apply-keyprotocol [^Editor ed ^BytePtr term ^long prot]
  (when (== prot (e KEYPROTOCOL_KITTY))
    (apply-builtin-tcap ed term (Ptr. (g ed builtin-kitty) 0) true))
  (when (== prot (e KEYPROTOCOL_MOK2))
    (apply-builtin-tcap ed term (Ptr. (g ed builtin-mok2) 0) true))
  (when-not (== prot (e KEYPROTOCOL_NONE))
    (accept-modifiers-for-function-keys ed)
    nil))

