          (if (or (not (== x2 58)) (== x3 -1) (and (not (== (bit-and (.get p) 0xff) (e NUL))) (not (== (bit-and (.get p) 0xff) 44))))
            (BytePtr. (g ed e-invalid-argument) 0)
