          (whim.cljhost/host-message ed (BytePtr. buf 0) -1 (e TRUE))
          nil)
      (do (whim.cljhost/vim-snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "\015\n'%s%s\015\n") (object-array [term (gettext_ ed (BytePtr/lit "' not known"))]))
