;; C: get_tty_info
(defn get-tty-info [^Editor ed ^long fd ^T_ttyinfo_T info]
  (let [^ints bs (int-array 1)
        ^ints intr (int-array 1)
        ^ints cr (int-array 1)
        ^ints nlcr (int-array 1)]
    (aset bs 0 (unchecked-int 0))
    (aset intr 0 (unchecked-int 0))
    (aset cr 0 (unchecked-int 0))
    (aset nlcr 0 (unchecked-int 0))
    (if (== (long (whim.cljhost/musl-tty-keys ed fd (IntPtr. bs 0) (IntPtr. intr 0) (IntPtr. cr 0) (IntPtr. nlcr 0))) (e OK))
      (do (.set-backspace info (u8 (long (aget bs 0))))
          (.set-interrupt info (u8 (long (aget intr 0))))
          (.set-enter info (if (zero? (long (aget cr 0))) (e CAR) (e NL)))
          (.set-nl-does-cr info (boolean (not (zero? (if (zero? (long (aget nlcr 0))) (e FALSE) (e TRUE))))))
          true)
      false)))

;; C: get_stty
(defn get-stty [^Editor ed]
  (let [^T_ttyinfo_T info (new-T_ttyinfo_T)
        ^bytes buf (byte-array 2)]
    (when (get-tty-info ed (g ed read-cmd-fd) info)
      (g! ed intr-char (.interrupt info))
      (aset buf 0 (unchecked-byte (.backspace info)))
      (aset buf 1 (unchecked-byte (e NUL)))
      (add-termcode ed (BytePtr/lit "kb") (BytePtr. buf 0) (e FALSE))
      (let [^BytePtr p (find-termcode ed (BytePtr/lit "kD"))]
        (when (and (some? p) (== (bit-and (.at p 0) 0xff) (bit-and (aget buf 0) 0xff)) (== (bit-and (.at p 1) 0xff) (bit-and (aget buf 1) 0xff)))
          (do-fixdel ed nil)
          nil)))))

;; C: vim_is_xterm
(defn vim-is-xterm? [^Editor ed ^BytePtr name_]
  (if (nil? name_)
    false
    (or (and (== (long (musl-strncasecmp ed name_ (BytePtr/lit "xterm") 5)) 0) (not (== (long (musl-strncasecmp ed name_ (BytePtr/lit "xterm-kitty") 11)) 0))) (== (long (musl-strncasecmp ed name_ (BytePtr/lit "nxterm") 6)) 0) (== (long (musl-strncasecmp ed name_ (BytePtr/lit "kterm") 5)) 0) (== (long (musl-strncasecmp ed name_ (BytePtr/lit "mlterm") 6)) 0) (== (long (musl-strncasecmp ed name_ (BytePtr/lit "rxvt") 4)) 0) (== (long (musl-strncasecmp ed name_ (BytePtr/lit "screen.xterm") 12)) 0) (== (long (musl-strcmp ed name_ (BytePtr/lit "builtin_xterm"))) 0))))

;; C: set_termname
(defn set-termname [^Editor ed ^BytePtr term]
  (let [^bytes name_ (byte-array 3)
        ^longs tl__ (long-array 2)
        ^objects to__ (object-array 1)
        width 0
        height 0
        ^BytePtr error-msg nil
        _ (g! ed detected-8bit (e FALSE))
        ^BytePtr term (if (term-is-builtin? ed term)
                        ^BytePtr (.add term 8)
                        term)
        ^Ptr termp (find-builtin-term ed term)]
    (if (nil? termp)
      (do (report-term-error ed error-msg term)
          (screen-start ed)
          (wait-return ed (e TRUE))
          false)
      (do (out-flush ed)
          (clear-termoptions ed)
          (parse-builtin-tcap ed term)
          (when (and (some? (musl-strstr ed term (BytePtr/lit "256color"))) (or (term-strings-not-set? ed (e KS_CCO)) (< (long (musl-atoi ed (aget (g ed term-strings) 49))) 256)))
            (apply-builtin-tcap ed term (Ptr. (g ed builtin-256colors) 0) true))
          (let [kpc (long (match-keyprotocol ed term))]
            (apply-keyprotocol ed term kpc)
            (if (== (long (musl-strcmp ed term (BytePtr/lit "pcterm"))) 0)
              (aset (g ed term-strings) 48 (BytePtr/lit "yes"))
              (aset (g ed term-strings) 48 (g ed empty-option)))
            (when (and (some? (musl-strstr ed term (BytePtr/lit "kitty"))) (or (nil? (aget (g ed term-strings) 69)) (== (bit-and (.get ^BytePtr (aget (g ed term-strings) 69)) 0xff) (e NUL))))
              (aset (g ed term-strings) 69 (BytePtr/lit "\033[>c")))
            (get-stty ed)
            (let [^BytePtr bs-p (find-termcode ed (BytePtr/lit "kb"))
                  ^BytePtr del-p (find-termcode ed (BytePtr/lit "kD"))
