  (.set-coladd ^T_pos_T (.-w-cursor wp) 0)
  (.set-lnum ^T_pos_T (.-w-pcmark wp) 1)
  (.set-col ^T_pos_T (.-w-pcmark wp) 0)
  (.set-lnum ^T_pos_T (.-w-prev-pcmark wp) 0)
  (.set-col ^T_pos_T (.-w-prev-pcmark wp) 0)
  (.set-w-topline wp 1)
  (.set-w-botline wp 2)
  (.set-w-valid wp 0)
  nil)

;; C: curwin_init
(defn curwin-init [^Editor ed]
  (win-init-empty ed (g ed curwin))
  nil)

;; C: snapshot_windows_scroll_size
(defn snapshot-windows-scroll-size [^Editor ed]
  (let [^S_window_S wp (g ed curwin)]
    (.set-w-last-topline wp (.w-topline wp))
    (.set-w-last-leftcol wp (.w-leftcol wp))
    (.set-w-last-skipcol wp (.w-skipcol wp))
    (.set-w-last-width wp (.w-width wp))
    (.set-w-last-height wp (.w-height wp))
    nil))

;; C: may_make_initial_scroll_size_snapshot
(defn may-make-initial-scroll-size-snapshot [^Editor ed]
  (when (zero? (g ed did-initial-scroll-size-snapshot))
    (g! ed did-initial-scroll-size-snapshot (e TRUE))
    (snapshot-windows-scroll-size ed)
    nil))

;; C: unuse_tabpage
(defn unuse-tabpage [^Editor ed ^S_tabpage_S tp]
  (.set-tp-topframe tp (g ed topframe))
  (.set-tp-curwin tp (g ed curwin))
  nil)

;; C: win_alloc
(defn win-alloc ^S_window_S [^Editor ed ^S_window_S after hidden]
  (let [^S_window_S new-wp (new-S_window_S)]
    (when (win-alloc-lines ed new-wp)
      (block-autocmds ed)
      (.set-w-wincol new-wp 0)
      (.set-w-width new-wp (i32 (aget (g ed Columns) 0)))
      (.set-w-topline new-wp 1)
      (.set-w-botline new-wp 2)
      (.set-lnum ^T_pos_T (.-w-cursor new-wp) 1)
      (.set-w-scbind-pos new-wp 1)
      (aset ^longs (.-wo-so ^T_winopt_T (.-w-onebuf-opt new-wp)) 0 -1)
      (aset ^longs (.-wo-so ^T_winopt_T (.-w-allbuf-opt new-wp)) 0 (aget ^longs (.-wo-so ^T_winopt_T (.-w-onebuf-opt new-wp)) 0))
      (aset ^longs (.-wo-sop ^T_winopt_T (.-w-onebuf-opt new-wp)) 0 -1)
      (aset ^longs (.-wo-sop ^T_winopt_T (.-w-allbuf-opt new-wp)) 0 (aget ^longs (.-wo-sop ^T_winopt_T (.-w-onebuf-opt new-wp)) 0))
      (aset ^longs (.-wo-siso ^T_winopt_T (.-w-onebuf-opt new-wp)) 0 -1)
      (aset ^longs (.-wo-siso ^T_winopt_T (.-w-allbuf-opt new-wp)) 0 (aget ^longs (.-wo-siso ^T_winopt_T (.-w-onebuf-opt new-wp)) 0))
      (.set-w-fraction new-wp 0)
      (.set-w-prev-fraction-row new-wp -1)
      (unblock-autocmds ed)
      (.set-w-next-match-id new-wp 1000)
      new-wp)))

;; C: new_frame
(defn new-frame [^Editor ed ^S_window_S wp]
  (let [^S_frame_S frp (new-S_frame_S)]
    (.set-w-frame wp frp)
    (.set-fr-layout frp (e FR_LEAF))
    (.set-fr-win frp wp)
    nil))

;; C: win_alloc_firstwin
(defn win-alloc-firstwin [^Editor ed ^S_window_S oldwin]
  (g! ed curwin (win-alloc ed nil false))
  (if (nil? (g ed curwin))
    false
    (do (g! ed curbuf (buflist-new ed 1 (e BLN_LISTED)))
        (if (nil? (g ed curbuf))
          false
          (do (.set-w-buffer (g ed curwin) (g ed curbuf))
              (.set-b-nwindows (g ed curbuf) 1)
              (curwin-init ed)
              (new-frame ed (g ed curwin))
              (if (nil? (.w-frame (g ed curwin)))
                false
                (do (g! ed topframe (.w-frame (g ed curwin)))
                    (.set-fr-width (g ed topframe) (i32 (aget (g ed Columns) 0)))
                    (.set-fr-height (g ed topframe) (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
                    true)))))))

;; C: alloc_tabpage
(defn alloc-tabpage ^S_tabpage_S [^Editor ed]
  (let [^S_tabpage_S tp (new-S_tabpage_S)]
    (.set-tp-ch-used tp (aget (g ed p-ch) 0))
    tp))

;; C: win_alloc_first
(defn win-alloc-first [^Editor ed]
  (if (win-alloc-firstwin ed nil)
    (do (g! ed curtab (alloc-tabpage ed))
        (unuse-tabpage ed (g ed curtab))
        true)
    false))

;; C: win_init_size
(defn win-init-size [^Editor ed]
  (.set-w-height (g ed curwin) (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
  (.set-w-prev-height (g ed curwin) (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
  (.set-fr-height (g ed topframe) (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
  (.set-w-width (g ed curwin) (.fr-width (g ed topframe)))
  nil)

;; C: create_windows
(defn create-windows [^Editor ed ^T_mparm_T parmp]
  (g! ed curbuf (.w-buffer (g ed curwin)))
  (when (nil? (.ml-root ^S_memline (.-b-ml (g ed curbuf))))
    (open-buffer ed))
  (ui-breakcheck ed)
  (if (zero? (g ed got-int))
    (do (g! ed curbuf (.w-buffer (g ed curwin)))
        nil)
    (do (vgetc ed)
        (g! ed curbuf (.w-buffer (g ed curwin)))
        nil)))

;; C: exe_commands
(defn exe-commands [^Editor ed ^T_mparm_T parmp]
  (g! ed msg-scroll (e TRUE))
  (when (<= (.lnum ^T_pos_T (.-w-cursor (g ed curwin))) 1)
    (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) 0))
  (estack-push ed (e ETYPE_ARGS) (BytePtr/lit "command line") 0)
  (let [i 0]
    (loop [i i]
      (if (< i (.n-commands parmp))
        (do (do-cmdline-cmd ed (aget ^objects (.-commands parmp) i))
            (let [i (i32 (inc i))]
              (recur i)))
        (do (estack-pop ed)
            (if (== (.lnum ^T_pos_T (.-w-cursor (g ed curwin))) 0)
              (do (.set-lnum ^T_pos_T (.-w-cursor (g ed curwin)) 1)
                  (g! ed msg-scroll (e FALSE))
                  nil)
              (do (g! ed msg-scroll (e FALSE))
                  nil)))))))

;; C: may_trigger_deferred_events
(defn may-trigger-deferred-events [^Editor ed]
  (when-not (g ed may-trigger-deferred-events-recursive)
    (g! ed may-trigger-deferred-events-recursive true)
    (update-topline ed)
    (validate-cursor ed)
    (g! ed may-trigger-deferred-events-recursive false)
    nil))

;; C: main_loop
(defn main-loop [^Editor ed cmdwin]
  (let [^S_oparg_S oa (new-S_oparg_S)
        ^S_oparg_S prev-oap (g ed current-oap)]
    (g! ed current-oap oa)
    (clear-oparg ed oa)
    (loop []
      (if cmdwin
        (do (g! ed current-oap prev-oap)
            nil)
        (do (when (stuff-empty? ed)
              (when-not (zero? (g ed need-wait-return))
                (wait-return ed (e FALSE)))
              (when (and (not (zero? (g ed need-start-insertmode))) (goto-im? ed) (zero? (g ed VIsual-active)))
                (g! ed need-start-insertmode (e FALSE))
                (stuffReadbuff ed (BytePtr/lit "i"))
                (g! ed need-fileinfo (e FALSE))))
            (when-not (zero? (g ed got-int))
              (when (zero? (g ed quit-more))
                (vgetc ed))
              (g! ed got-int (e FALSE)))
            (g! ed msg-scroll (e FALSE))
            (g! ed quit-more (e FALSE))
            (if (zero? (g ed skip-redraw))
              (when (or (not (zero? (g ed do-redraw))) (stuff-empty? ed))
                (may-trigger-deferred-events ed)
                (may-trigger-safestate ed (and (not (op-pending? ed)) (== (g ed restart-edit) 0)))
                (update-topline ed)
                (validate-cursor ed)
                (if (zero? (g ed VIsual-active))
                  (if (zero? (g ed must-redraw))
                    (when (or (not (zero? (g ed redraw-cmdline))) (not (zero? (g ed clear-cmdline))) (not (zero? (g ed redraw-mode))))
                      (showmode ed))
                    (update-screen ed 0))
                  (update-curbuf ed (e UPD_INVERTED)))
                (redraw-statuslines ed)
                (when (some? (g ed keep-msg))
                  (let [^BytePtr p (vim-strsave ed (g ed keep-msg))]
                    (g! ed msg-hist-off (e TRUE))
                    (msg-attr ed p (g ed keep-msg-attr))
                    (g! ed msg-hist-off (e FALSE))))
                (when-not (zero? (g ed need-fileinfo))
                  (fileinfo ed (e FALSE) true false)
                  (g! ed need-fileinfo (e FALSE)))
                (g! ed emsg-on-display (e FALSE))
                (g! ed did-emsg (e FALSE))
                (g! ed msg-didany (e FALSE))
                (may-clear-sb-text ed)
                (showruler ed false)
                (setcursor ed)
                (cursor-on ed)
                (g! ed do-redraw (e FALSE))
                (may-make-initial-scroll-size-snapshot ed))
              (do (g! ed skip-redraw (e FALSE))
                  (setcursor ed)
                  (cursor-on ed)))
            (may-send-t-RK ed)
            (update-curswant ed)
            (normal-cmd ed oa true)
            (recur))))))

;; C: vim_main2
(defn vim-main2 ^long [^Editor ed]
  (g! ed starting (e NO_BUFFERS))
  (g! ed no-wait-return (e FALSE))
  (g! ed msg-scroll (e FALSE))
  (when (and (or (not (zero? (g ed did-emsg))) (not (zero? (g ed msg-didout)))) (not (== (bit-and (.get ^BytePtr (aget (g ed term-strings) 42)) 0xff) (e NUL))))
    (g! ed newline-on-exit (e TRUE)))
  (term-enter ed)
  (when (or (not (zero? (g ed need-wait-return))) (not (zero? (g ed msg-didany))))
    (wait-return ed (e TRUE)))
  (starttermcap ed)
  (when-not (zero? (g ed scroll-region))
    (scroll-region-reset ed))
  (scroll-start ed)
  (screenclear ed)
  (g! ed no-wait-return (e TRUE))
  (create-windows ed (g ed params))
  (setpcmark ed)
  (shorten-fnames ed)
  (when (> (.n-commands (g ed params)) 0)
    (exe-commands ed (g ed params)))
  (g! ed starting 0)
  (g! ed RedrawingDisabled 0)
  (redraw-all-later ed (e UPD_NOT_VALID))
  (g! ed no-wait-return (e FALSE))
  (when-not (zero? (long (aget (g ed p-im) 0)))
    (g! ed need-start-insertmode (e TRUE)))
  (if (== (g ed restart-edit) 0)
    (do (g! ed do-redraw (e TRUE))
        (main-loop ed false)
        0)
    (do (stuffcharReadbuff ed (e K_NOP))
        (g! ed do-redraw (e TRUE))
        (main-loop ed false)
        0)))

;; C: common_init_1
(defn common-init-1 [^Editor ed]
  (estack-init ed)
  (cmdline-init ed)
  (let [i 0]
    (loop [i i]
      (if (< i 256)
        (do (aset (g ed mb-bytelen-tab) i (unchecked-byte 1))
            (let [i (i32 (inc i))]
              (recur i)))
        (do (g! ed IObuff (BytePtr/alloc 1025))
            (let [t1 (nil? (g ed IObuff))
                  t1 (if t1
                       t1
                       (do (g! ed NameBuff (BytePtr/alloc (e PATH_MAX)))
                           (nil? (g ed NameBuff))))]
              (when t1
                (mch-exit ed 0)
                nil)))))))

;; C: common_init_2
(defn common-init-2 [^Editor ed ^T_mparm_T paramp]
  (if (win-alloc-first ed)
    (do (init-yank ed)
        (set-init-1 ed)
        nil)
    (do (mch-exit ed 0)
        (init-yank ed)
        (set-init-1 ed)
        nil)))

(defn mainerr [^Editor ed ^long n ^BytePtr str_]
  (let [^bytes buf (byte-array 1024)]
    (init-longVersion ed)
    (if (some? str_)
      (do (whim.cljhost/vim-snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s: \"%s\"") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main-errors) n)) str_]))
          (whim.cljhost/host-message ed (BytePtr. buf 0) -1 (e TRUE))
          (mch-exit ed 1)
          nil)
      (do (whim.cljhost/vim-snprintf ed (BytePtr. buf 0) 1024 (BytePtr/lit "%s\n%s") (object-array [(g ed longVersion) (gettext_ ed (aget (g ed main-errors) n))]))
          (whim.cljhost/host-message ed (BytePtr. buf 0) -1 (e TRUE))
          (mch-exit ed 1)
          nil))))

;; C: command_line_scan
(defn command-line-scan [^Editor ed ^T_mparm_T parmp]
  (let [^longs tl__ (long-array 2)
        ^objects to__ (object-array 1)
        argc (.argc parmp)
        ^Ptr argv (.argv parmp)
        argc (i32 (dec argc))
        ^Ptr argv (.add argv 1)
        argv-idx 1]
    (loop [argc argc
           ^Ptr argv argv
           argv-idx argv-idx]
      (when (> argc 0)
        (let [argv-idx (if (== (long (.at ^BytePtr (.at argv 0) 0)) 43)
                         (do (when (>= (.n-commands parmp) (e MAX_ARG_CMDS))
                               (mainerr ed (e ME_EXTRA_CMD) nil))
                             (let [argv-idx -1]
                               (if (== (long (.at ^BytePtr (.at argv 0) 1)) (e NUL))
                                 (let [t1 (.n-commands parmp)]
                                   (.set-n-commands parmp (i32 (inc (.n-commands parmp))))
                                   (aset ^objects (.-commands parmp) t1 (BytePtr/lit "$"))
                                   argv-idx)
                                 (let [t2 (.n-commands parmp)]
                                   (.set-n-commands parmp (i32 (inc (.n-commands parmp))))
                                   (aset ^objects (.-commands parmp) t2 (.add ^BytePtr (.at argv 0) 1))
                                   argv-idx))))
                         (do (mainerr ed (e ME_UNKNOWN_OPTION) (.at argv 0))
                             argv-idx))
              j__1 (if (or (<= argv-idx 0) (== (long (.at ^BytePtr (.at argv 0) argv-idx)) (e NUL)))
                     (let [argc (i32 (dec argc))
                           ^Ptr argv (.add argv 1)
                           argv-idx 1]
                       (aset tl__ 0 argc)
                       (aset to__ 0 argv)
                       (aset tl__ 1 argv-idx)
                       0)
                     (do (aset tl__ 0 argc)
                         (aset to__ 0 argv)
                         (aset tl__ 1 argv-idx)
                         0))
              argc (aget tl__ 0)
              ^Ptr argv (aget to__ 0)
              argv-idx (aget tl__ 1)]
          (recur argc argv argv-idx))))))

;; C: vim_main
(defn vim-main ^long [^Editor ed ^long argc ^Ptr argv]
  (.zero (g ed params))
  (.set-argc (g ed params) argc)
  (.set-argv (g ed params) argv)
  (.set-want-full-screen (g ed params) (boolean true))
  (common-init-1 ed)
  (common-init-2 ed (g ed params))
  (command-line-scan ed (g ed params))
  (g! ed RedrawingDisabled (i32 (inc (g ed RedrawingDisabled))))
  (mch-init ed)
  (when (.want-full-screen (g ed params))
    (termcapinit ed)
    (screen-start ed))
  (ui-get-shellsize ed)
  (win-init-size ed)
  (g! ed cmdline-row (i32 (- (aget (g ed Rows) 0) (aget (g ed p-ch) 0))))
  (g! ed cmdline-col-off 0)
  (g! ed cmdline-width (i32 (aget (g ed Columns) 0)))
  (g! ed msg-row (g ed cmdline-row))
  (g! ed msg-col 0)
  (screenalloc ed false)
  (set-init-2 ed)
  (g! ed msg-scroll (e TRUE))
  (g! ed no-wait-return (e TRUE))
  (init-mappings ed)
  (init-highlight ed true false)
  (long (vim-main2 ed)))

;; The tables the file-scope arrays of structs start with, as data (clj_tables.go).

(defn- row-long "A number of a table's row: itself, or an enumerator's by its name." ^long [v]
  (if (symbol? v) (long (get enumerators v)) (long v)))

(defn- fill-S_clinterval!
  "Fill the S_clinterval objects of a from rows, a table's: one row an element, nil one left zero."
  [^objects a rows]
  (loop [i 0
         rows (seq rows)]
    (when rows
      (when-some [r (first rows)]
        (let [^S_clinterval o (aget a i)]
          (.set-first_ o (row-long (nth r 0)))
          (.set-last_ o (row-long (nth r 1)))
          (.set-class_ o (row-long (nth r 2)))))
      (recur (inc i) (next rows)))))

