          (.set-cmd-minlen o (row-long (nth r 1)))
          (.set-cmd-func o (when-some [s (nth r 2)] @(ns-resolve 'whim.editor s)))
          (.set-cmd-argt o (row-long (nth r 3)))
          (.set-cmd-addr-type o (row-long (nth r 4)))))
